CREATE TABLE "public"."ArtistsLocations" (
  "id"         bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "artist"     text,
  "birthplace" text,
  "area"       text,
  "country"    text,
  CONSTRAINT "ArtistsLocations_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."ArtistsLocations"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."SongsEmotions" (
  "id"           bigint  NOT NULL,
  "joy"          numeric,
  "trust"        numeric,
  "anticipation" numeric,
  "surprise"     numeric,
  "fear"         numeric,
  "sadness"      numeric,
  "disgust"      numeric,
  "anger"        numeric,
  "positive"     numeric,
  "negative"     numeric,
  "neutral"      numeric,
  CONSTRAINT "SongsEmotions_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."SongsEmotions"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."Songs" (
  "id"       bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name"     text,
  "length"   text,
  "genre"    text,
  "album"    text,
  "date"     date,
  "artistId" bigint,
  CONSTRAINT "Songs_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."Songs"
  ENABLE ROW LEVEL SECURITY;

ALTER TABLE "public"."Songs"
  ADD CONSTRAINT "Songs_artistId_fkey" FOREIGN KEY ("artistId") REFERENCES public."ArtistsLocations"(id);

ALTER TABLE "public"."SongsEmotions"
  ADD CONSTRAINT "SongsEmotions_id_fkey" FOREIGN KEY (id) REFERENCES public."Songs"(id);

